"""Compare generated bytes even before the first Git commit."""
import hashlib
from pathlib import Path

root = Path(__file__).resolve().parent.parent
paths = [root / "backend/api", root / "backend/internal/platform/database/dbgen",
         root / "backend/tests/contracts/fixturedb", root / "frontend/src/app/api/generated",
         root / "frontend/src/app/api/fixture-generated"]
for directory in paths:
    for path in sorted(directory.rglob("*")):
        if path.is_file():
            print(hashlib.sha256(path.read_bytes()).hexdigest(), path.relative_to(root))
fixture = root / "backend/tests/contracts/openapi-fixture.json"
if fixture.exists():
    print(hashlib.sha256(fixture.read_bytes()).hexdigest(), fixture.relative_to(root))
